function openRules(e){e.preventDefault(),e.stopPropagation(),document.getElementById("rules-modal").classList.add("open")}function closeRules(){document.getElementById("rules-modal").classList.remove("open"),document.getElementById("rules-check").checked=!0;const e=document.getElementById("rules-checkmark");e&&e.classList.remove("error"),document.getElementById("rules-error").style.display="none"}function setupRulesModalClosers(){document.getElementById("rules-modal").addEventListener("click",e=>{e.target===document.getElementById("rules-modal")&&closeRules()})}